def _cache(key, cfp):
    if not Path(cfp).exists(): return None
    with open(cfp) as f:
        line = first(f, lambda l: json.loads(l)["key"] == key)
        return json.loads(line) if line else None

# %% ../nbs/00_core.ipynb #93c30488
resp_norm_pats = []
resp_keep = {'response': ['id','object','status','model','output','usage','error','incomplete_details','created_at','completed_at']}

def _prune(o):
    if isinstance(o, list): return [_prune(v) for v in o]
    if not isinstance(o, dict): return o
    ks = resp_keep.get(o['object']) if isinstance(o.get('object'), str) else None
    return {k:_prune(v) for k,v in o.items() if not ks or k in ks}

def _norm_resp(txt):
    "Apply `resp_norm_pats`, then prune echo-carrying JSON resources to their `resp_keep` fields"
    for pat,repl in resp_norm_pats: txt = re.sub(pat, repl, txt)
    if not resp_keep: return txt
    def j(s):
        "Pruned re-serialization of JSON `s`, or `s` untouched (byte-exact) when nothing prunes"
        try: o = json.loads(s)
        except json.JSONDecodeError: return None
        p = _prune(o)
        return json.dumps(p) if p!=o else s
    if (r := j(txt)) is not None: return r
    def f(l):
        if not l.startswith('data: '): return l
        return 'data: '+r if (r := j(l[6:])) is not None else l
    return '\n'.join(f(l) for l in txt.split('\n'))

# %% ../nbs/00_core.ipynb #d8100f2f
def _write_cache(key, content, cfp, hdrs, status_code=200, binary=False):
    if not binary: content = _norm_resp(content)
    cfp = Path(cfp)
    lk = os.open(cfp.parent, os.O_RDONLY)
    try:
        fcntl.flock(lk, fcntl.LOCK_EX)
        recs = {(d:=json.loads(l))['key']: d for l in cfp.read_text().splitlines() if l.strip()} if cfp.exists() else {}
        recs[key] = dict(key=key, response=content, headers=hdrs, status_code=status_code, binary=binary)
        with atomic_save(cfp, mode='w') as f:
            for d in sorted(recs.values(), key=lambda d: (d['response'], d['key'])): f.write(json.dumps(d)+"\n")
    finally: os.close(lk)

