def _req_resp_from_cache(c, request):
    "Build a `requests.Response` from cache entry `c`."
    res = requests.Response()
    res.status_code = c.get('status_code', 200)
    res._content = base64.b64decode(c['response']) if c.get('binary') else c['response'].encode()
    res.headers = requests.structures.CaseInsensitiveDict(c.get('headers') or {})
    res.encoding = requests.utils.get_encoding_from_headers(res.headers)
    res.url,res.request = request.url,request
    return res

def _req_send(cfp, doms, self, request, debug=False, hdrs=None, **kwargs):
    body = request.body or b''
    hreq = httpx.Request(request.method, request.url, headers=dict(request.headers), content=body.encode() if isinstance(body,str) else body)
    key,cached = _check(hreq, doms, cfp, kwargs.get('stream'), debug, mk_resp=_req_resp_from_cache)
    if cached is not None: return cached
    if key is None: return self._orig_send(request, **kwargs)
    res = self._orig_send(request, **kwargs)
    res.headers = requests.structures.CaseInsensitiveDict(_save_resp(key, res.content, res, cfp, hdrs))
    return res

def _apply_requests_patch(cfp, doms, hdrs=None, debug=False):
    @patch
    def send(self:requests.adapters.HTTPAdapter, request, **kwargs):
        return _req_send(cfp, doms, self, request, debug=debug, hdrs=hdrs, **kwargs)

# %% ../nbs/00_core.ipynb #99a750c1
def _apply_sync_patch(cfp, doms, hdrs=None, debug=False):
    @patch
    def send(self:httpx._client.Client, request, **kwargs): return _send(cfp, doms, self, request, debug=debug, hdrs=hdrs, **kwargs)
    if httpx2:
        @patch
        def send(self:httpx2._client.Client, request, **kwargs): return _send(cfp, doms, self, request, debug=debug, hdrs=hdrs, **kwargs)

# %% ../nbs/00_core.ipynb #76a06201
def _apply_async_patch(cfp, doms, hdrs=None, debug=False):
    @patch
    async def send(self:AsyncClient, request, **kwargs): return await _asend(cfp, doms, self, request, debug=debug, hdrs=hdrs, **kwargs)
    if httpx2:
        @patch
        async def send(self:httpx2.AsyncClient, request, **kwargs): return await _asend(cfp, doms, self, request, debug=debug, hdrs=hdrs, **kwargs)

