_cfg = None

def enable_cachy(
    cache_dir=None, # Folder for `cachy.jsonl`; default: the nearest folder at or above the cwd with a `pyproject.toml`, else the cwd
    doms=doms, # Domains whose requests are cached
    hdrs=None, # Response headers to store; default: all except `content-encoding`
    debug=False # Print what happens to each request; `'miss'` prints only misses
):
    "Patch httpx, httpx2 and requests to serve requests to `doms` from `cachy.jsonl` and record new responses"
    global _cfg
    disable_cachy()
    if hdrs is None: hdrs=[]
    cfp = Path(cache_dir or find_file_parents("pyproject.toml") or ".") / "cachy.jsonl"
    cfp.touch(exist_ok=True)
    _apply_sync_patch    (cfp, doms, hdrs, debug)
    _apply_async_patch   (cfp, doms, hdrs, debug)
    _apply_requests_patch(cfp, doms, hdrs, debug)
    _cfg = dict(cache_dir=cache_dir, doms=doms, hdrs=hdrs, debug=debug)

# %% ../nbs/00_core.ipynb #3be9fe57
def disable_cachy():
    global _cfg
    _cfg = None
    if hasattr(AsyncClient, '_orig_send'):
        AsyncClient.send  = AsyncClient._orig_send
        httpx.Client.send = httpx.Client._orig_send
    if httpx2 and hasattr(httpx2.AsyncClient, '_orig_send'):
        httpx2.AsyncClient.send = httpx2.AsyncClient._orig_send
        httpx2.Client.send      = httpx2.Client._orig_send
    if hasattr(requests.adapters.HTTPAdapter, '_orig_send'):
        requests.adapters.HTTPAdapter.send = requests.adapters.HTTPAdapter._orig_send

