@contextmanager
def no_cachy():
    "Send requests live within the block, without reading or writing the cache"
    tok = _off.set(True)
    try: yield
    finally: _off.reset(tok)

# %% ../nbs/00_core.ipynb #0214cb34
@contextmanager
@delegates(enable_cachy)
def cachy(**kwargs):
    "Enable cachy within the block, then restore the previous state"
    old = _cfg
    enable_cachy(**kwargs)
    try: yield
    finally: enable_cachy(**old) if old else disable_cachy()
